<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}$id=filter_var($_POST['loan_id']??null,FILTER_VALIDATE_INT);if(!$id){$_SESSION['error']='A valid loan record is required.';header('Location: ../?page=library');exit;}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,book_id,returned_on FROM library_loans WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$loan=$q->fetch();if(!$loan||$loan['returned_on']!==null)throw new DomainException('This loan was already returned or could not be found.');$q=$pdo->prepare('UPDATE library_loans SET returned_on=CURDATE(),returned_by=:user WHERE id=:id AND returned_on IS NULL');$q->execute(['user'=>$user['id'],'id'=>$id]);audit_log('library.book_returned','library_loans',$id,['book_id'=>(int)$loan['book_id']]);$pdo->commit();$_SESSION['notice']='Book return recorded.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Library return failed: '.$e->getMessage());$_SESSION['error']='Could not record the book return.';}header('Location: ../?page=library');exit;
